python3 -c "import csv, math;
data = []
with open('data/housing_data.csv', mode='r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        try:
            price = float(row['price'])
            area = float(row['area'])
            data.append((price, area))
        except (ValueError, TypeError):
            continue
if not data:
    print('No data')
else:
    n = len(data)
    sum_x = sum(d[0] for d in data)
    sum_y = sum(d[1] for d in data)
    sum_x_sq = sum(d[0]**2 for d in data)
    sum_y_sq = sum(d[1]**2 for d in data)
    sum_xy = sum(d[0]*d[1] for d in data)

    num = (n * sum_xy) - (sum_x * sum_y)
    den = math.sqrt(((n * sum_x_sq) - (sum_x**2)) * ((n * sum_y_sq) - (sum_y**2)))
    if den == 0:
        print('0.00')
    else:
        print(f'{num/den:.2f}')"
